sketches.source:
setcpm(40/4)

// The room gathers, two rounds of bowls, a deep round, then stillness
song("gather@4 bath@16 bath'@16 deep@16 still@8", "once")

// Bowls struck one at a time, each left to ring out
// The second round answers a fifth higher
bowls: note("<c4 ~ g4 ~ eb4 ~ ~ bb3>").s("sine").fm(1.2).fmh(2.76)
  .decay(8).sustain(0).release(8)
  .pan(sine.slow(8)).space("hall").gain(.24)
  .variant(x => x.add(7))
  .sections("bath")

// A large bowl, slightly out of tune with the others, so they beat gently
const strike = x => x.s("sine").fm(.8).fmh(2.41)
  .decay(10).sustain(0).release(10).room(.8).size(.95)

// It opens every section, and the stillness begins with one last strike
greatbowl: strike(note("<c3 ~ ~ ~ ~ ~ ~ ~>")).gain(.28).exceptSections("deep")

// In the deep round it sounds twice as often, answered by a low fifth
deepbowl: strike(note("<c3 ~ ~ ~ g2 ~ ~ ~>")).gain(.3).sections("deep")

// The hum underneath, with a faint overtone whistle, fading out at the end
const tone = note("c2").slow(8).s("hum").overtone(6)
hum: tone.gain(.16).exceptSections("still")
humfade: tone.gain(env(".16 0", "section")).sections("still")

// Soft air in the room
air: s("pink").slow(8).lpf(600).gain(bysec("gather:.05 still:.02 *:.03"))

setcpm(48/4)

// Settle, chant, breathe, chant again, sit in silence, return and close
song("settle@4 (mantra@12 1.breath@4 2.silent@8)*2 return@12 close@4", "once")

// The last breaths lengthen
tempomap("0:12 52:12 56:9")

// So on the in-breath, hum on the out-breath: one breath every two cycles
// Each section restarts the part, so 'so' always falls on an in-breath
mantra: note("g3 d3").slow(2)
  .s("voice").syl("<so hu>").voicetype("alto")
  .mono(1).vglide(.2).attack(.6).release(2)
  .space("hall").gain(bysec("breath:.2 *:.34"))
  .sections("mantra breath return")

// A ringing drone on the tonic and fifth
drone: note("d2 a2 d3 a2").slow(2).s("sawtooth").timbre("bright")
  .unison(2).detune(.08).attack(.02).decay(2).sustain(.4).release(3)
  .lpf(1400).room(.6).gain(bysec("settle:.12 close:.1 *:.18"))

// The hum underneath
hum: note("d2").slow(8).s("hum").overtone(5).gain(.16)

setcpm(40/4)

// One region of the body every eight cycles, from the feet to the crown, then rest
song("feet@8 legs@8 belly@8 chest@8 throat@8 crown@8 rest@8", "once")

// The rest slows down
tempomap("0:10 48:10 56:8")

// A guiding hum that circles you twice in every region
// It rises in pitch and height as your attention moves up the body
guide: note("<a3 e4>").slow(4)
  .add(bysec("feet:0 legs:2 belly:3 chest:5 throat:7 crown:12"))
  .s("hum")
  .azimuth(saw.range(-180, 180).slow(4))
  .elevation(bysec("feet:-40 legs:-25 belly:-10 chest:5 throat:20 crown:45"))
  .distance(2).posglide(.5).attack(2).release(3).gain(.3)
  .exceptSections("rest")

// A still drone at the centre
drone: note("[a1,e2]").slow(8).s("sine").attack(4).sustain(1).release(6)
  .gain(bysec("rest:.18 *:.22"))

// Soft air all around
air: s("pink").slow(8).lpf(500).gain(.03)

// A small bell as each region begins: every section restarts it at its first cycle
bell: note("<a4 ~ ~ ~ ~ ~ ~ ~>").s("sine").fm(2).fmh(2.76)
  .decay(5).sustain(0).release(5).space("hall").gain(.12)
  .sections("feet legs belly chest throat crown rest")

setcpm(40/4)

// Settle, descend, rest deep, then fade away
song("settle@8 descend@16 deep@32 fade@8", "once")

// Everything slows as you fall asleep
tempomap("0:10 24:10 56:8 64:6")

// A slow binaural drone: each ear is detuned by half the beat
const tone = note("<a1 a1 f1 g1>").slow(4).s("sine")
  .attack(4).sustain(1).release(6)

// The beat starts at 4 Hz and steps down to 2 Hz
drone: tone.binaural(bysec("settle:4 descend:3 *:2")).gain(.32)
  .exceptSections("fade")
dronefade: tone.binaural(2).gain(env(".32 0", "section"))
  .sections("fade")

// A pad that barely moves
pad: note("<[a2,e3,b3] [f2,c3,g3]>").slow(8)
  .s("sawtooth").unison(4).detune(.3)
  .attack(6).release(8).lpf(600).room(.8).size(.95)
  .gain(bysec("settle:.06 fade:.05 *:.1"))

// Warm brown noise, like a distant waterfall
bed: s("brown").slow(8).lpf(400).gain(.08)

setcpm(44/4)

// Arrive, drift twice through two answering halves, then return
song("arrive@8 (drift@16 drift'@16)*2 return@8", "once")

// The binaural beat: 8 Hz to arrive, 6 Hz to drift, 10 Hz to return. Keep the volume low
drone: note("<d2 d2 bb1 c2>").slow(4).s("sine")
  .binaural(bysec("arrive:8 return:10 *:6"))
  .attack(4).sustain(1).release(6).gain(.3)

// Slow, breathing choir chords, answered an octave higher
// Each chord lasts two cycles, so each vowel is written twice to change with it
choir: note("<[d3,a3,f4] [bb2,f3,d4] [g2,d3,bb3] [a2,e3,c#4]>").slow(2)
  .s("choir").syl("<oo oo ah ah oh oh oo oo>")
  .attack(3).release(4).space("hall").gain(.24)
  .variant(x => x.syl("<ah ah oo oo oo oo ah ah>").add(12).gain(.18))
  .sections("drift")

// A stream nearby, closer as you return
stream: s("stream").slow(4).distance(4).gain(bysec("return:.26 *:.18"))
